// Keep fixed words aligned with the level-config swaps in index.html.
// The same permutation is applied to EN, DE, and TR so startup validation and
// the playable boards always use the words belonging to the current level.
const FIXED_LEVEL_SWAPS = [
  [10, 288],  // 11 <-> 289
  [32, 292],  // 33 <-> 293
  [46, 296],  // 47 <-> 297
  [85, 794],  // 86 <-> 795
  [99, 795],  // 100 <-> 796
  [111, 797], // 112 <-> 798
  [132, 798], // 133 <-> 799
];

Object.values(GARDEN_OF_WORDS_FIXED_LEVEL_DATA).forEach((levels) => {
  FIXED_LEVEL_SWAPS.forEach(([leftIndex, rightIndex]) => {
    [levels[leftIndex], levels[rightIndex]] = [levels[rightIndex], levels[leftIndex]];
  });
});

// Curated replacements for the repeated Easy sets in beds 61, 84, 169, 321,
// and 790. Bed 1 remains the reference set; these revisions are applied after
// the level-alignment swaps so the numbers below always mean playable beds.
const MANUAL_LEVEL_WORD_REVISIONS = {
  en: {
    61: ["LEAF", "ROOT", "SEED", "SOIL"],
    84: ["STAR", "MOON", "CLOUD", "DUSK"],
    169: ["ROAD", "PATH", "TRAIL", "CROSS"],
    321: ["WAVE", "TIDE", "SAND", "SHELL"],
    790: ["BREAD", "MILK", "RICE", "SOUP"]
  },
  de: {
    61: ["BAUM", "BLATT", "ERDE", "SAMEN"],
    84: ["MOND", "STERN", "NACHT", "WOLKE"],
    169: ["FELD", "WALD", "SEE", "HÜGEL"],
    321: ["WELLE", "SAND", "UFER", "MEER"],
    790: ["BROT", "MILCH", "REIS", "SUPPE"]
  },
  tr: {
    61: ["AĞAÇ", "KÖK", "DAL", "ÇİÇEK"],
    84: ["GECE", "BULUT", "GÜNEŞ", "GÜN"],
    169: ["YOL", "KÖPRÜ", "KAPI", "DUVAR"],
    321: ["DALGA", "KUM", "SAHİL", "KAYIK"],
    790: ["EKMEK", "SÜT", "PİLAV", "ÇORBA"]
  }
};
Object.entries(MANUAL_LEVEL_WORD_REVISIONS).forEach(([language, revisions]) => {
  Object.entries(revisions).forEach(([levelId, words]) => {
    GARDEN_OF_WORDS_FIXED_LEVEL_DATA[language][Number(levelId) - 1] = words;
  });
});


